page Sim "/" {
  state balls: Any[] = []
  state frames = 0
  state paused = false
  ref cv
  ref raf

  fn make() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r: 10
    }
  }

  fn step(list) {
    const W = 400
    const H = 300
    for (const b of list) {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if (b.x < b.r) { b.x = b.r; b.vx = -b.vx }
      if (b.x > W - b.r) { b.x = W - b.r; b.vx = -b.vx }
      if (b.y < b.r) { b.y = b.r; b.vy = -b.vy }
      if (b.y > H - b.r) { b.y = H - b.r; b.vy = -b.vy }
    }
    for (let i = 0; i < list.length; i++) {
      for (let j = i + 1; j < list.length; j++) {
        const a = list[i]
        const c = list[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        const min = a.r + c.r
        if (dist < min) {
          if (dist == 0) { dx = 1; dy = 0; dist = 1 }
          const nx = dx / dist
          const ny = dy / dist
          const overlap = (min - dist) / 2
          a.x -= nx * overlap
          a.y -= ny * overlap
          c.x += nx * overlap
          c.y += ny * overlap
          const rel = (c.vx - a.vx) * nx + (c.vy - a.vy) * ny
          if (rel < 0) {
            const tvx = a.vx
            const tvy = a.vy
            a.vx = c.vx
            a.vy = c.vy
            c.vx = tvx
            c.vy = tvy
          }
          for (const b of [a, c]) {
            if (b.x < b.r) b.x = b.r
            if (b.x > W - b.r) b.x = W - b.r
            if (b.y < b.r) b.y = b.r
            if (b.y > H - b.r) b.y = H - b.r
          }
        }
      }
    }
  }

  fn draw(list) {
    if (!cv) { return }
    const ctx = cv.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#3b82f6"
    for (const b of list) {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn tick() {
    if (!paused) {
      step(balls)
      frames++
    }
    draw(balls)
    raf = requestAnimationFrame(tick)
  }

  fn add() {
    balls = [...balls, make()]
  }

  fn reset() {
    balls = Array.from({ length: 5 }, () => make())
    frames = 0
  }

  mount {
    balls = Array.from({ length: 5 }, () => make())
    raf = requestAnimationFrame(tick)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=2 {
    canvas ref=cv id="sim" width=400 height=300
    row gap=2 {
      button "Agregar" -> add()
      button paused ? "Reanudar" : "Pausar" -> paused = !paused
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${balls.length}`
    text `Cuadros: ${frames}`
  }
}

page Sim "/" {
  state balls: Any[] = []
  state frames = 0
  state paused = false
  ref cv
  ref raf

  fn make() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r: 10
    }
  }

  fn step() {
    for (const b of balls) {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) }
      if (b.x > 400 - b.r) { b.x = 400 - b.r; b.vx = -Math.abs(b.vx) }
      if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) }
      if (b.y > 300 - b.r) { b.y = 300 - b.r; b.vy = -Math.abs(b.vy) }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i]
        const b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let d = Math.sqrt(dx * dx + dy * dy)
        const min = a.r + b.r
        if (d < min) {
          if (d == 0) { dx = 1; dy = 0; d = 1 }
          const nx = dx / d
          const ny = dy / d
          const push = (min - d) / 2
          a.x -= nx * push
          a.y -= ny * push
          b.x += nx * push
          b.y += ny * push
          const tvx = a.vx
          const tvy = a.vy
          a.vx = b.vx
          a.vy = b.vy
          b.vx = tvx
          b.vy = tvy
          for (const p of [a, b]) {
            p.x = Math.min(Math.max(p.x, p.r), 400 - p.r)
            p.y = Math.min(Math.max(p.y, p.r), 300 - p.r)
          }
        }
      }
    }
  }

  fn draw() {
    if (!cv) { return }
    const ctx = cv.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#3b82f6"
    for (const b of balls) {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn tick() {
    if (!paused) {
      step()
      draw()
      frames++
    }
    raf = requestAnimationFrame(tick)
  }

  fn add() {
    balls = [...balls, make()]
    draw()
  }

  fn reset() {
    balls = Array.from({ length: 5 }, () => make())
    frames = 0
    draw()
  }

  mount {
    balls = Array.from({ length: 5 }, () => make())
    raf = requestAnimationFrame(tick)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=2 {
    canvas ref=cv id="sim" width=400 height=300
    row gap=2 {
      button "Agregar" primary -> add()
      button paused ? "Reanudar" : "Pausar" -> paused = !paused
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${balls.length}`
    text `Cuadros: ${frames}`
  }
}
